package com.inventra.backend.service;
import com.inventra.backend.dto.*; import com.inventra.backend.exception.*; import com.inventra.backend.model.Product; import com.inventra.backend.repository.ProductRepository; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class ProductService { private final ProductRepository repo; public ProductService(ProductRepository r){repo=r;} public ProductResponse createProduct(ProductRequest r){if(repo.existsBySku(r.getSku()))throw new DuplicateSkuException("Product with SKU '"+r.getSku()+"' already exists");Product p=new Product();apply(p,r);return map(repo.save(p));} public ProductResponse update(String id,ProductRequest r){Product p=repo.findById(id).orElseThrow(()->new ProductNotFoundException("Product with id '"+id+"' not found"));if(!p.getSku().equalsIgnoreCase(r.getSku())&&repo.existsBySku(r.getSku()))throw new DuplicateSkuException("Product with SKU '"+r.getSku()+"' already exists");apply(p,r);return map(repo.save(p));} public void delete(String id){if(!repo.existsById(id))throw new ProductNotFoundException("Product with id '"+id+"' not found");repo.deleteById(id);} public ProductResponse getProductById(String id){return map(repo.findById(id).orElseThrow(()->new ProductNotFoundException("Product with id '"+id+"' not found")));} public List<ProductResponse> getAllProducts(){return repo.findAll().stream().map(this::map).toList();} public List<ProductResponse> getLowStockProducts(){return repo.findLowStockProducts().stream().map(this::map).toList();} public ProductPageResponse getProducts(Pageable p){Page<Product> page=repo.findAll(p);return new ProductPageResponse(page.getContent().stream().map(this::map).toList(),page.getNumber(),page.getSize(),page.getTotalElements(),page.getTotalPages());} private void apply(Product p,ProductRequest r){p.setSku(r.getSku().trim());p.setName(r.getName().trim());p.setCategory(r.getCategory().trim());p.setPrice(r.getPrice());p.setStockQuantity(r.getStockQuantity());p.setReorderLevel(r.getReorderLevel());p.setLeadTimeDays(r.getLeadTimeDays()==null?7:r.getLeadTimeDays());} private ProductResponse map(Product p){return new ProductResponse(p.getId(),p.getSku(),p.getName(),p.getCategory(),p.getPrice(),p.getStockQuantity(),p.getReorderLevel(),p.getLeadTimeDays());}}
